using System;using System.IO;using System.Linq;using System.Collections.Generic;using Musikbox;
class ImportExportTests{static void Main(string[] a){string root=a[0];Directory.CreateDirectory(root);string source=Path.Combine(root,"000 Country");Directory.CreateDirectory(source);File.Copy(a[1],Path.Combine(source,"Titel.mp3"));var before=File.ReadAllBytes(Path.Combine(source,"Titel.mp3"));var warnings=new List<string>();var project=new Project{Folders=Importer.Read(source,warnings)};if(warnings.Count!=0||project.Folders.Count!=1||project.Folders[0].Songs.Count!=1)throw new Exception("Import fehlgeschlagen");Console.WriteLine("OK echter Ordnerimport inklusive ID3v2.4");var song=project.Folders[0].Songs[0];song.Year="2026";song.Genre="Test";song.Comment="Kommentar äöü";string output=Exporter.Export(project,root,()=>{},(x,y)=>{});string file=Directory.GetFiles(output,"*.mp3",SearchOption.AllDirectories).Single();var read=MediaMetadata.Read(file);if(read.Year!=song.Year||read.Genre!=song.Genre||read.Comment!=song.Comment)throw new Exception("Erweiterte Tags beim Export verloren");Console.WriteLine("OK Musikbox-Export mit Jahr, Genre und Kommentar");if(!File.ReadAllBytes(song.Source).SequenceEqual(before))throw new Exception("Original verändert");Console.WriteLine("OK Original bytegleich");bool cancelled=false;try{Exporter.Export(project,root,()=>{throw new OperationCanceledException();},(x,y)=>{});}catch(OperationCanceledException){cancelled=true;}if(!cancelled||Directory.GetDirectories(root,".Musikbox-unvollstaendig-*").Length!=0)throw new Exception("Abbruch unvollständig");Console.WriteLine("OK Abbruch des Musikbox-Exports räumt Teilkopien auf");}}
